import { buildWaves } from "../lib/spec-orchestrator.js";
import {
  type ApiError,
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  apiFetchText,
  decodeOutputLines,
  normalizeKey,
  notify,
  pad,
  resolveWorkspace,
  timeAgo,
  truncate,
} from "./shared.js";

type RunStatus =
  | "queued"
  | "running"
  | "paused"
  | "cancelling"
  | "cancelled"
  | "passed"
  | "failed"
  | "partial_failure"
  | "done"
  | "skipped"
  | "pass"
  | "fail"
  | "pending"
  | "retrying"
  | "merged"
  | string;

type StorySpec = {
  id: string;
  title: string;
  dependsOn?: string[];
  agent?: string;
  suggestedSkills?: string[];
  reroute?: { fromEngine: string; toEngine: string; reason: string };
};

type RunStory = {
  story_id: string;
  status: string;
  retries?: number;
  started_at?: string | null;
  finished_at?: string | null;
  elapsed_seconds?: number | null;
  model_used?: string | null;
  input_tokens?: number | null;
  output_tokens?: number | null;
  cost_usd?: number | null;
};

type StoryTokenBreakdown = {
  storyId: string;
  status: string;
  inputTokens: number;
  outputTokens: number;
  modelUsed: string | null;
  costUsd: number;
};

type RunStateStory = {
  storyId: string;
  retries?: number;
  elapsedMs?: number;
  failReason?: string;
};

type RunStateDecision = {
  storyId: string;
  timestamp: string;
  type: string;
  description: string;
};

type RunState = {
  specId: string;
  runId: number;
  startedAt: string;
  lastUpdatedAt: string;
  completedStories: RunStateStory[];
  failedStories: RunStateStory[];
  skippedStories: RunStateStory[];
  currentStory: string | null;
  decisions: RunStateDecision[];
  resumedFromStory?: string | null;
};

type ContextComparison = {
  predicted: Record<string, { totalTokens: number; injectedFiles: string[] }>;
  actual: Record<string, { contextFiles: string[] }>;
};

type RunPayload = {
  run: {
    id: number;
    status: RunStatus;
    spec_path?: string;
    started_at?: string;
    finished_at?: string | null;
    agent_model?: string | null;
    agent_type?: string | null;
    summary?: string | null;
    merge_status?: string | null;
    queue_position?: number | null;
    workspace_id?: string | number;
  };
  stories?: RunStory[];
  specStories?: StorySpec[];
  specModel?: string | null;
  agentType?: string | null;
  agentModel?: string | null;
  worktreePath?: string | null;
  branchName?: string | null;
  includeGraph?: boolean;
  tokenSummary?: {
    inputTokens: number;
    outputTokens: number;
    totalCostUsd: number;
  };
  storyTokenBreakdown?: StoryTokenBreakdown[];
  runState?: RunState | null;
  contextComparison?: ContextComparison | null;
};

type StoryOutputPayload = {
  storyId: string;
  runId: number;
  status: string;
  retries: number;
  failureReason?: string | null;
  failureAttempts?: number | null;
  blockedBy?: string[] | null;
  output?: string[];
  lineCount?: number;
};

type RetryResponse = {
  ok?: boolean;
  queued?: boolean;
  jobId?: string;
  runId?: number | string;
};

type StoryView = {
  id: string;
  title: string;
  dependsOn: string[];
  status: RunStatus;
  agent?: string;
  suggestedSkills: string[];
  reroute?: { fromEngine: string; toEngine: string; reason: string };
  retries: number;
  startedAt?: string | null;
  finishedAt?: string | null;
  elapsedSeconds?: number | null;
  failureReason?: string | null;
  modelUsed?: string | null;
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
  predictedContextTokens: number;
  predictedContextFiles: string[];
  actualContextFiles: string[];
};

type StoryCollection = {
  stories: StoryView[];
  waves: StoryView[][];
};

type Pane = "output" | "story" | "run" | "log" | "commits";

type RunCommit = {
  sha: string;
  message: string;
  date: string;
  author: string;
};

type RunCommitsPayload = {
  commits?: RunCommit[];
  branchName?: string | null;
};

function normalizeStatus(status: string | undefined): RunStatus {
  switch (status) {
    case "pass":
    case "passed":
      return "passed";
    case "fail":
    case "failed":
      return "failed";
    case "skip":
    case "skipped":
      return "skipped";
    default:
      return status ?? "pending";
  }
}

function statusIcon(status: string | undefined): string {
  switch (normalizeStatus(status)) {
    case "queued":
      return "◌";
    case "running":
      return "↻";
    case "paused":
      return "⏸";
    case "cancelling":
      return "!";
    case "cancelled":
      return "⊘";
    case "passed":
    case "done":
    case "merged":
      return "✓";
    case "failed":
    case "partial_failure":
      return "✗";
    case "skipped":
      return "↷";
    case "retrying":
      return "↺";
    default:
      return "·";
  }
}

function formatStatus(status: string | undefined): string {
  return normalizeStatus(status).replace(/_/g, " ");
}

function formatTokens(value: number | null | undefined): string {
  const amount = value ?? 0;
  if (amount >= 1_000_000) {
    return `${(amount / 1_000_000).toFixed(1)}M`;
  }
  if (amount >= 1_000) {
    return `${(amount / 1_000).toFixed(1)}k`;
  }
  return String(amount);
}

function formatCurrency(value: number | null | undefined): string {
  return `$${(value ?? 0).toFixed(3)}`;
}

function formatDuration(seconds: number | null | undefined): string {
  if (seconds == null || !Number.isFinite(seconds)) {
    return "unknown";
  }

  if (seconds < 60) {
    return `${Math.max(0, Math.floor(seconds))}s`;
  }

  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return `${minutes}m ${Math.floor(seconds % 60)}s`;
  }

  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m`;
}

function formatList(values: string[], empty = "none"): string {
  return values.length > 0 ? values.join(", ") : empty;
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "unknown";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function countStatuses(stories: StoryView[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const story of stories) {
    const key = normalizeStatus(story.status);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts;
}

function getStoryStateStatuses(runState: RunState | null | undefined) {
  const completed = new Set((runState?.completedStories ?? []).map((story) => story.storyId));
  const failed = new Set((runState?.failedStories ?? []).map((story) => story.storyId));
  const skipped = new Set((runState?.skippedStories ?? []).map((story) => story.storyId));
  const current = runState?.currentStory ?? null;
  const failureReasons = new Map((runState?.failedStories ?? []).map((story) => [story.storyId, story.failReason ?? null] as const));

  return { completed, failed, skipped, current, failureReasons };
}

function buildStories(payload: RunPayload): StoryCollection {
  const resultById = new Map<string, RunStory>();
  for (const story of payload.stories ?? []) {
    resultById.set(story.story_id, story);
  }

  const tokensById = new Map<string, StoryTokenBreakdown>();
  for (const token of payload.storyTokenBreakdown ?? []) {
    tokensById.set(token.storyId, token);
  }

  const predictedContextById = new Map(Object.entries(payload.contextComparison?.predicted ?? {}));
  const actualContextById = new Map(Object.entries(payload.contextComparison?.actual ?? {}));
  const stateStatus = getStoryStateStatuses(payload.runState);
  const stories: StoryView[] = [];
  const seen = new Set<string>();

  const inferStatus = (storyId: string, resultStatus?: string): RunStatus => {
    if (resultStatus) {
      return normalizeStatus(resultStatus);
    }
    if (stateStatus.current === storyId) {
      return "running";
    }
    if (stateStatus.failed.has(storyId)) {
      return "failed";
    }
    if (stateStatus.skipped.has(storyId)) {
      return "skipped";
    }
    if (stateStatus.completed.has(storyId)) {
      return "passed";
    }
    return "pending";
  };

  for (const specStory of payload.specStories ?? []) {
    const result = resultById.get(specStory.id);
    const token = tokensById.get(specStory.id);
    const predictedContext = predictedContextById.get(specStory.id);
    const actualContext = actualContextById.get(specStory.id);
    stories.push({
      id: specStory.id,
      title: specStory.title,
      dependsOn: specStory.dependsOn ?? [],
      status: inferStatus(specStory.id, result?.status),
      agent: specStory.agent,
      suggestedSkills: specStory.suggestedSkills ?? [],
      reroute: specStory.reroute,
      retries: result?.retries ?? 0,
      startedAt: result?.started_at,
      finishedAt: result?.finished_at,
      elapsedSeconds: result?.elapsed_seconds ?? null,
      failureReason: stateStatus.failureReasons.get(specStory.id) ?? null,
      modelUsed: result?.model_used ?? token?.modelUsed ?? null,
      inputTokens: token?.inputTokens ?? result?.input_tokens ?? 0,
      outputTokens: token?.outputTokens ?? result?.output_tokens ?? 0,
      costUsd: token?.costUsd ?? result?.cost_usd ?? 0,
      predictedContextTokens: predictedContext?.totalTokens ?? 0,
      predictedContextFiles: predictedContext?.injectedFiles ?? [],
      actualContextFiles: actualContext?.contextFiles ?? [],
    });
    seen.add(specStory.id);
  }

  for (const result of payload.stories ?? []) {
    if (seen.has(result.story_id)) {
      continue;
    }
    const token = tokensById.get(result.story_id);
    const predictedContext = predictedContextById.get(result.story_id);
    const actualContext = actualContextById.get(result.story_id);
    stories.push({
      id: result.story_id,
      title: result.story_id,
      dependsOn: [],
      status: inferStatus(result.story_id, result.status),
      suggestedSkills: [],
      retries: result.retries ?? 0,
      startedAt: result.started_at,
      finishedAt: result.finished_at,
      elapsedSeconds: result.elapsed_seconds ?? null,
      failureReason: stateStatus.failureReasons.get(result.story_id) ?? null,
      modelUsed: result.model_used ?? token?.modelUsed ?? null,
      inputTokens: token?.inputTokens ?? result.input_tokens ?? 0,
      outputTokens: token?.outputTokens ?? result.output_tokens ?? 0,
      costUsd: token?.costUsd ?? result.cost_usd ?? 0,
      predictedContextTokens: predictedContext?.totalTokens ?? 0,
      predictedContextFiles: predictedContext?.injectedFiles ?? [],
      actualContextFiles: actualContext?.contextFiles ?? [],
    });
  }

  const byId = new Map(stories.map((story) => [story.id, story] as const));
  const waves: StoryView[][] = [];

  if ((payload.specStories ?? []).length > 0) {
    try {
      const computed = buildWaves(
        (payload.specStories ?? []).map((story) => ({
          id: story.id,
          title: story.title,
          description: story.title,
          acceptanceCriteria: [],
          dependsOn: story.dependsOn ?? [],
        })),
      );

      for (const wave of computed) {
        waves.push(wave.map((story) => byId.get(story.id)).filter((story): story is StoryView => Boolean(story)));
      }
    } catch {
      // Fall back to a flat story list when dependency metadata is malformed.
    }
  }

  if (waves.length === 0 && stories.length > 0) {
    waves.push([...stories]);
  }

  const seenInWaves = new Set(waves.flatMap((wave) => wave.map((story) => story.id)));
  const orphanStories = stories.filter((story) => !seenInWaves.has(story.id));
  if (orphanStories.length > 0) {
    waves.push(orphanStories);
  }

  return { stories, waves };
}

function chooseStoryId(stories: StoryView[], currentStoryId: string | null): string | null {
  if (stories.length === 0) {
    return null;
  }
  if (currentStoryId && stories.some((story) => story.id === currentStoryId)) {
    return currentStoryId;
  }

  const preferred =
    stories.find((story) => normalizeStatus(story.status) === "running") ??
    stories.find((story) => normalizeStatus(story.status) === "failed") ??
    stories.find((story) => normalizeStatus(story.status) === "queued") ??
    stories[0];

  return preferred?.id ?? null;
}

function wrapSimple(text: string, width: number): string[] {
  const safeWidth = Math.max(10, width);
  const lines: string[] = [];
  const normalized = text.replace(/\s+/g, " ").trim();
  if (!normalized) {
    return [""];
  }

  let remaining = normalized;
  while (remaining.length > safeWidth) {
    const slice = remaining.slice(0, safeWidth + 1);
    const breakAt = Math.max(slice.lastIndexOf(" "), safeWidth - 8);
    const next = remaining.slice(0, breakAt).trimEnd();
    lines.push(next);
    remaining = remaining.slice(Math.max(1, breakAt)).trimStart();
  }
  lines.push(remaining);
  return lines;
}

function renderBodyColumns(leftLines: string[], rightLines: string[], width: number): string[] {
  const safeWidth = Math.max(80, width);
  const leftWidth = Math.max(28, Math.floor(safeWidth * 0.43));
  const rightWidth = Math.max(28, safeWidth - leftWidth - 3);
  const rows = Math.max(leftLines.length, rightLines.length);
  const lines: string[] = [];

  for (let index = 0; index < rows; index += 1) {
    const left = pad(truncate(leftLines[index] ?? "", leftWidth), leftWidth);
    const right = truncate(rightLines[index] ?? "", rightWidth);
    lines.push(`${left} │ ${right}`);
  }

  return lines;
}

function renderStoryList(stories: StoryView[], waves: StoryView[][], selectedStoryId: string | null, width: number): string[] {
  const lines: string[] = [truncate(`Stories (${stories.length})`, width), ""];

  if (stories.length === 0) {
    lines.push("No story activity has been recorded for this run yet.");
    return lines;
  }

  waves.forEach((wave, waveIndex) => {
    const counts = countStatuses(wave);
    const summary = [
      `${counts.get("running") ?? 0} running`,
      `${counts.get("passed") ?? 0} passed`,
      `${counts.get("failed") ?? 0} failed`,
    ].join(" • ");
    lines.push(truncate(`Wave ${waveIndex + 1} — ${summary}`, width));
    for (const story of wave) {
      const marker = story.id === selectedStoryId ? ">" : " ";
      const retryBadge = story.retries > 0 ? ` • retry ${story.retries}` : "";
      const blockedBadge = story.dependsOn.length > 0 && normalizeStatus(story.status) === "pending" ? ` • waits ${story.dependsOn.length}` : "";
      const headline = `${marker} ${statusIcon(story.status)} ${story.id}${retryBadge}${blockedBadge}`;
      lines.push(truncate(headline, width));
      lines.push(truncate(`   ${story.title}`, width));
      if (story.failureReason) {
        lines.push(truncate(`   Failure: ${story.failureReason}`, width));
      }
    }
    lines.push("");
  });

  return lines;
}

function buildOutputPane(story: StoryView | undefined, output: StoryOutputPayload | null, width: number): string[] {
  const lines: string[] = [truncate(`Output${story ? ` — ${story.id}` : ""}`, width), ""];

  if (!story) {
    lines.push("Select a story to inspect its live output.");
    return lines;
  }

  lines.push(truncate(story.title, width));
  lines.push(truncate(`Status ${formatStatus(story.status)} • retries ${story.retries} • model ${story.modelUsed || "auto"}`, width));

  if (output?.failureReason) {
    lines.push(truncate(`Failure: ${output.failureReason}`, width));
  }
  if ((output?.blockedBy ?? []).length > 0) {
    lines.push(truncate(`Blocked by: ${formatList(output?.blockedBy ?? [])}`, width));
  }

  lines.push("");

  const outputLines = decodeOutputLines(output).slice(-14);
  if (outputLines.length === 0) {
    lines.push("No captured story output yet.");
  } else {
    for (const line of outputLines) {
      lines.push(truncate(line, width));
    }
  }

  return lines;
}

function buildStoryPane(story: StoryView | undefined, width: number): string[] {
  const lines: string[] = [truncate(`Story${story ? ` — ${story.id}` : ""}`, width), ""];

  if (!story) {
    lines.push("Select a story to inspect execution metadata.");
    return lines;
  }

  lines.push(truncate(story.title, width));
  lines.push(truncate(`Status: ${formatStatus(story.status)}`, width));
  lines.push(truncate(`Agent: ${story.agent || story.modelUsed || "auto"}`, width));
  lines.push(truncate(`Depends on: ${formatList(story.dependsOn)}`, width));
  lines.push(truncate(`Suggested skills: ${formatList(story.suggestedSkills)}`, width));
  lines.push(truncate(`Duration: ${formatDuration(story.elapsedSeconds)}`, width));
  lines.push(truncate(`Tokens: in ${formatTokens(story.inputTokens)} • out ${formatTokens(story.outputTokens)} • ${formatCurrency(story.costUsd)}`, width));

  const predictedFiles = story.predictedContextFiles;
  const actualFiles = story.actualContextFiles;
  if (predictedFiles.length > 0 || actualFiles.length > 0 || story.predictedContextTokens > 0) {
    lines.push("");
    lines.push(truncate(`Context plan: ${predictedFiles.length} files • ${formatTokens(story.predictedContextTokens)} predicted tokens`, width));
    lines.push(truncate(`Context used: ${actualFiles.length} files`, width));

    const missing = predictedFiles.filter((file) => !actualFiles.includes(file));
    const extra = actualFiles.filter((file) => !predictedFiles.includes(file));
    if (missing.length === 0 && extra.length === 0 && actualFiles.length > 0) {
      lines.push(truncate("Context drift: none", width));
    } else {
      lines.push(truncate(`Context drift: ${missing.length} missing • ${extra.length} extra`, width));
    }

    if (missing.length > 0) {
      lines.push(truncate(`Missing: ${missing.slice(0, 2).join(", ")}${missing.length > 2 ? " …" : ""}`, width));
    }
    if (extra.length > 0) {
      lines.push(truncate(`Extra: ${extra.slice(0, 2).join(", ")}${extra.length > 2 ? " …" : ""}`, width));
    }
  }

  if (story.failureReason) {
    lines.push("");
    lines.push(truncate(`Failure: ${story.failureReason}`, width));
  }

  if (story.startedAt) {
    lines.push(truncate(`Started: ${timeAgo(story.startedAt)}`, width));
  }
  if (story.finishedAt) {
    lines.push(truncate(`Finished: ${timeAgo(story.finishedAt)}`, width));
  }
  if (story.reroute) {
    lines.push("");
    lines.push(truncate(`Rerouted ${story.reroute.fromEngine} → ${story.reroute.toEngine}`, width));
    for (const line of wrapSimple(story.reroute.reason, width)) {
      lines.push(truncate(line, width));
    }
  }

  return lines;
}

function buildRunPane(payload: RunPayload | null, workspaceLabel: string, stories: StoryView[], width: number): string[] {
  const lines: string[] = ["Run summary", ""];

  if (!payload) {
    lines.push("Loading run metadata...");
    return lines;
  }

  const counts = countStatuses(stories);
  const decisions = payload.runState?.decisions?.slice(-3) ?? [];
  const startedAt = payload.run.started_at ? timeAgo(payload.run.started_at) : "unknown";
  const finishedAt = payload.run.finished_at ? timeAgo(payload.run.finished_at) : "still active";

  lines.push(truncate(`Spec: ${extractSpecSlug(payload.run.spec_path)}`, width));
  lines.push(truncate(`Workspace: ${workspaceLabel}`, width));
  lines.push(truncate(`Status: ${formatStatus(payload.run.status)}`, width));
  lines.push(truncate(`Started: ${startedAt} • Finished: ${finishedAt}`, width));
  lines.push(truncate(`Stories: ${stories.length} total • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed`, width));
  lines.push(truncate(`Tokens: in ${formatTokens(payload.tokenSummary?.inputTokens)} • out ${formatTokens(payload.tokenSummary?.outputTokens)} • ${formatCurrency(payload.tokenSummary?.totalCostUsd)}`, width));
  lines.push(truncate(`Model: ${payload.agentModel || payload.run.agent_model || payload.specModel || "auto"}`, width));
  lines.push(truncate(`Branch: ${payload.branchName || "n/a"}`, width));
  lines.push(truncate(`Worktree: ${payload.worktreePath || "n/a"}`, width));

  if (payload.run.queue_position != null) {
    lines.push(truncate(`Queue position: ${payload.run.queue_position}`, width));
  }
  if (payload.run.merge_status) {
    lines.push(truncate(`Merge status: ${payload.run.merge_status}`, width));
  }
  if (payload.runState?.currentStory) {
    lines.push(truncate(`Current story: ${payload.runState.currentStory}`, width));
  }
  if (payload.run.summary) {
    lines.push("");
    lines.push("Summary:");
    for (const line of wrapSimple(payload.run.summary, width)) {
      lines.push(truncate(line, width));
    }
  }
  if (decisions.length > 0) {
    lines.push("");
    lines.push("Recent decisions:");
    for (const decision of decisions) {
      lines.push(truncate(`- ${decision.storyId}: ${decision.type}`, width));
      for (const line of wrapSimple(decision.description, Math.max(16, width - 2))) {
        lines.push(truncate(`  ${line}`, width));
      }
    }
  }

  return lines;
}

function isRetryableRun(status: RunStatus): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "failed" || normalized === "done" || normalized === "partial_failure";
}

function isPausableRun(status: RunStatus): boolean {
  return normalizeStatus(status) === "running";
}

function isResumableRun(status: RunStatus): boolean {
  return normalizeStatus(status) === "paused";
}

function isCancellableRun(status: RunStatus): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "queued" || normalized === "running" || normalized === "paused";
}

function buildLogPane(logLines: string[], logError: string | null, width: number): string[] {
  const lines: string[] = ["Run log", ""];

  if (logError) {
    lines.push(truncate(logError, width));
    return lines;
  }

  if (logLines.length === 0) {
    lines.push("No run log is available yet.");
    return lines;
  }

  for (const line of logLines.slice(-18)) {
    lines.push(truncate(line, width));
  }

  return lines;
}

function buildCommitsPane(commits: RunCommit[], branchName: string | null, commitsError: string | null, width: number): string[] {
  const lines: string[] = ["Run commits", ""];

  if (branchName) {
    lines.push(truncate(`Branch: ${branchName}`, width));
    lines.push("");
  }

  if (commitsError) {
    lines.push(truncate(commitsError, width));
    return lines;
  }

  if (commits.length === 0) {
    lines.push("No run-specific commits detected yet.");
    return lines;
  }

  for (const commit of commits.slice(0, 8)) {
    lines.push(truncate(`${commit.sha.slice(0, 7)}  ${commit.message}`, width));
    lines.push(truncate(`   ${commit.author} • ${timeAgo(commit.date)}`, width));
  }

  return lines;
}

function canRetryMerge(payload: RunPayload | null): boolean {
  return payload?.run.merge_status === "failed";
}

export async function openRunView(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  initialRunId: number,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    let busy = true;
    let runId = initialRunId;
    let workspaceLabel = "Loading workspace…";
    let payload: RunPayload | null = null;
    let collection: StoryCollection = { stories: [], waves: [] };
    let selectedStoryId: string | null = null;
    let selectedOutput: StoryOutputPayload | null = null;
    let runLogLines: string[] = [];
    let runLogError: string | null = null;
    let runCommits: RunCommit[] = [];
    let runCommitsBranchName: string | null = null;
    let runCommitsError: string | null = null;
    let pane: Pane = "output";
    let statusLine = `Loading run ${runId}…`;
    let refreshTimer: NodeJS.Timeout | undefined;
    let resolvedWorkspaceId: string | null = null;

    const requestRender = () => {
      if (mounted) {
        tui.requestRender();
      }
    };

    const resolveWorkspaceLabel = async (workspaceId: string | number | undefined) => {
      const nextId = workspaceId == null ? null : String(workspaceId);
      if (!nextId || nextId === resolvedWorkspaceId) {
        return;
      }

      try {
        const workspace = await resolveWorkspace(baseUrl, token, nextId);
        resolvedWorkspaceId = workspace.id;
        workspaceLabel = workspace.label;
      } catch {
        resolvedWorkspaceId = nextId;
        workspaceLabel = nextId;
      }
    };

    const refreshSelectedOutput = async () => {
      const selected = collection.stories.find((story) => story.id === selectedStoryId);
      if (!selected) {
        selectedOutput = null;
        return;
      }

      try {
        selectedOutput = await apiFetchJson<StoryOutputPayload>(
          baseUrl,
          `/api/pipeline/runs/${runId}/stories/${encodeURIComponent(selected.id)}/output?lines=200`,
          { token },
        );
      } catch (error) {
        const apiError = error as ApiError;
        if (apiError.status === 404) {
          selectedOutput = null;
          return;
        }
        throw error;
      }
    };

    const refreshRunLog = async () => {
      try {
        const text = await apiFetchText(baseUrl, `/api/pipeline/runs/${runId}/log`, { token });
        runLogLines = text.split(/\r?\n/);
        runLogError = null;
      } catch (error) {
        const apiError = error as ApiError;
        runLogLines = [];
        runLogError = apiError.status === 404 ? "Run log not available yet." : `Run log unavailable: ${error instanceof Error ? error.message : String(error)}`;
      }
    };

    const refreshRunCommits = async () => {
      try {
        const response = await apiFetchJson<RunCommitsPayload>(baseUrl, `/api/pipeline/runs/${runId}/commits`, { token });
        runCommits = response.commits ?? [];
        runCommitsBranchName = response.branchName ?? null;
        runCommitsError = null;
      } catch (error) {
        const apiError = error as ApiError;
        runCommits = [];
        runCommitsBranchName = null;
        runCommitsError = apiError.status === 404 ? "Run commits are not available for this run." : `Run commits unavailable: ${error instanceof Error ? error.message : String(error)}`;
      }
    };

    const syncRun = async () => {
      payload = await apiFetchJson<RunPayload>(baseUrl, `/api/pipeline/runs/${runId}`, { token });
      await resolveWorkspaceLabel(payload.run.workspace_id);
      collection = buildStories(payload);
      selectedStoryId = chooseStoryId(collection.stories, selectedStoryId ?? payload.runState?.currentStory ?? null);
      await refreshSelectedOutput();
      if (pane === "log") {
        await refreshRunLog();
      }
      if (pane === "commits") {
        await refreshRunCommits();
      }
      const counts = countStatuses(collection.stories);
      statusLine = `Run ${runId} • ${formatStatus(payload.run.status)} • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed`;
    };

    const runAction = (label: string, action: () => Promise<void>) => {
      if (busy) {
        return;
      }

      busy = true;
      statusLine = label;
      requestRender();

      void (async () => {
        try {
          await action();
          await syncRun();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Error: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          requestRender();
        }
      })();
    };

    const close = () => {
      mounted = false;
      if (refreshTimer) {
        clearInterval(refreshTimer);
      }
      done();
    };

    const selectStory = (delta: number) => {
      const currentIndex = Math.max(0, collection.stories.findIndex((story) => story.id === selectedStoryId));
      const nextIndex = Math.max(0, Math.min(collection.stories.length - 1, currentIndex + delta));
      const nextStory = collection.stories[nextIndex];
      if (!nextStory || nextStory.id === selectedStoryId) {
        return;
      }

      selectedStoryId = nextStory.id;
      statusLine = `Focused ${nextStory.id}`;
      requestRender();

      void refreshSelectedOutput().then(requestRender).catch((error) => {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Output refresh failed: ${message}`;
        requestRender();
      });
    };

    const cyclePane = () => {
      pane = pane === "output" ? "story" : pane === "story" ? "run" : pane === "run" ? "log" : pane === "log" ? "commits" : "output";
      statusLine = `Pane: ${pane}`;
      requestRender();
      if (pane === "log") {
        void refreshRunLog().then(requestRender);
      }
      if (pane === "commits") {
        void refreshRunCommits().then(requestRender);
      }
    };

    const refreshNow = () => {
      runAction(`Refreshing run ${runId}…`, async () => {
        await syncRun();
      });
    };

    const openRunLog = () => {
      pane = "log";
      runAction(`Loading run log for ${runId}…`, async () => {
        await refreshRunLog();
      });
    };

    const openRunCommits = () => {
      pane = "commits";
      runAction(`Loading run commits for ${runId}…`, async () => {
        await refreshRunCommits();
      });
    };

    const cancelRun = () => {
      if (!payload || !isCancellableRun(payload.run.status)) {
        return;
      }

      runAction(`Cancelling run ${runId}…`, async () => {
        const confirmed = (await ctx.ui.confirm?.("Cancel run", `Cancel run ${runId}?`)) ?? false;
        if (!confirmed) {
          statusLine = `Cancel aborted for run ${runId}`;
          return;
        }
        await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/cancel`, { method: "POST", token });
        notify(ctx.ui, `Cancellation requested for run ${runId}`, "warning");
      });
    };

    const pauseOrResumeRun = () => {
      if (!payload) {
        return;
      }

      if (isPausableRun(payload.run.status)) {
        runAction(`Pausing run ${runId}…`, async () => {
          await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/pause`, { method: "POST", token });
          notify(ctx.ui, `Paused run ${runId}`, "warning");
        });
        return;
      }

      if (isResumableRun(payload.run.status)) {
        runAction(`Resuming run ${runId}…`, async () => {
          await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/resume`, { method: "POST", token });
          notify(ctx.ui, `Resumed run ${runId}`, "success");
        });
      }
    };

    const retryFailedStories = () => {
      if (!payload || !isRetryableRun(payload.run.status)) {
        return;
      }

      const failedStoryIds = collection.stories
        .filter((story) => {
          const status = normalizeStatus(story.status);
          return status === "failed" || status === "skipped";
        })
        .map((story) => story.id);

      if (failedStoryIds.length === 0) {
        statusLine = "No failed or skipped stories to retry.";
        requestRender();
        return;
      }

      runAction(`Retrying ${failedStoryIds.length} stories…`, async () => {
        const confirmed =
          (await ctx.ui.confirm?.("Retry failed stories", `Queue a retry for ${failedStoryIds.length} failed or skipped stories?`)) ?? false;
        if (!confirmed) {
          statusLine = "Retry cancelled.";
          return;
        }

        const response = await apiFetchJson<RetryResponse>(baseUrl, `/api/pipeline/runs/${runId}/retry`, {
          method: "POST",
          token,
          body: { storyIds: failedStoryIds },
        });

        const nextRunId = Number(response.runId);
        if (Number.isFinite(nextRunId) && nextRunId > 0) {
          runId = nextRunId;
          selectedStoryId = null;
          selectedOutput = null;
          statusLine = `Attached to retry run ${runId}`;
          notify(ctx.ui, `Attached to retry run ${runId}`, "success");
        }
      });
    };

    const retryMerge = () => {
      if (!canRetryMerge(payload)) {
        return;
      }

      runAction(`Retrying merge for run ${runId}…`, async () => {
        const confirmed =
          (await ctx.ui.confirm?.("Retry failed merge", `Retry the failed auto-merge for run ${runId}?`)) ?? false;
        if (!confirmed) {
          statusLine = "Merge retry cancelled.";
          return;
        }

        await apiFetchJson(baseUrl, `/api/pipeline/runs/${runId}/retry-merge`, {
          method: "POST",
          token,
        });
        notify(ctx.ui, `Queued merge retry for run ${runId}`, "success");
      });
    };

    void (async () => {
      try {
        await syncRun();
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        statusLine = `Failed to load run ${runId}: ${message}`;
        notify(ctx.ui, message, "error");
      } finally {
        busy = false;
        refreshTimer = setInterval(() => {
          if (!mounted || busy) {
            return;
          }
          void syncRun().then(requestRender).catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            statusLine = `Refresh failed: ${message}`;
            requestRender();
          });
        }, 3_000);
        requestRender();
      }
    })();

    return {
      handleInput(data: string) {
        const key = normalizeKey(data);

        if (key === "q" || key === "escape" || key === "ctrl+c") {
          close();
          return;
        }

        if (key === "tab") {
          cyclePane();
          return;
        }

        if (busy) {
          return;
        }

        if (key === "down" || key === "j") {
          selectStory(1);
          return;
        }

        if (key === "up" || key === "k") {
          selectStory(-1);
          return;
        }

        if (key === "r") {
          refreshNow();
          return;
        }

        if (key === "c") {
          cancelRun();
          return;
        }

        if (key === "p") {
          pauseOrResumeRun();
          return;
        }

        if (key === "f") {
          retryFailedStories();
          return;
        }

        if (key === "m") {
          retryMerge();
          return;
        }

        if (key === "l") {
          openRunLog();
          return;
        }

        if (key === "g") {
          openRunCommits();
        }
      },

      render(width: number): string[] {
        const safeWidth = Math.max(60, width);
        const selectedStory = collection.stories.find((story) => story.id === selectedStoryId);
        const specSlug = extractSpecSlug(payload?.run.spec_path);
        const counts = countStatuses(collection.stories);
        const failedStories = collection.stories.filter((story) => normalizeStatus(story.status) === "failed");
        const currentStory = payload?.runState?.currentStory ?? collection.stories.find((story) => normalizeStatus(story.status) === "running")?.id ?? null;
        const header = [
          truncate(`Rorca Run Cockpit — Run ${runId}`, safeWidth),
          truncate(
            `Status ${payload ? formatStatus(payload.run.status) : "loading"} • Workspace ${workspaceLabel} • Spec ${specSlug} • Started ${payload?.run.started_at ? timeAgo(payload.run.started_at) : "unknown"}`,
            safeWidth,
          ),
          truncate(
            `Stories ${collection.stories.length} • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed • Tokens ${formatTokens(payload?.tokenSummary?.inputTokens)} / ${formatTokens(payload?.tokenSummary?.outputTokens)} • ${formatCurrency(payload?.tokenSummary?.totalCostUsd)}`,
            safeWidth,
          ),
          truncate(
            failedStories.length > 0
              ? `Attention: ${failedStories.length} failed • ${failedStories.slice(0, 2).map((story) => story.id).join(", ")}${failedStories.length > 2 ? " …" : ""}`
              : currentStory
                ? `Active story: ${currentStory}`
                : payload?.run.merge_status === "failed"
                  ? "Attention: auto-merge failed — press m to retry merge"
                  : "No active alerts.",
            safeWidth,
          ),
          "",
        ];

        const leftLines = renderStoryList(collection.stories, collection.waves, selectedStoryId, Math.max(24, Math.floor(safeWidth * 0.43)));
        const rightWidth = safeWidth >= 100 ? Math.max(28, safeWidth - Math.max(28, Math.floor(safeWidth * 0.43)) - 3) : safeWidth;
        const rightLines =
          pane === "output"
            ? buildOutputPane(selectedStory, selectedOutput, rightWidth)
            : pane === "story"
              ? buildStoryPane(selectedStory, rightWidth)
              : pane === "run"
                ? buildRunPane(payload, workspaceLabel, collection.stories, rightWidth)
                : pane === "log"
                  ? buildLogPane(runLogLines, runLogError, rightWidth)
                  : buildCommitsPane(runCommits, runCommitsBranchName, runCommitsError, rightWidth);

        const body = safeWidth >= 100
          ? renderBodyColumns(leftLines, rightLines, safeWidth)
          : [
              ...leftLines.map((line) => truncate(line, safeWidth)),
              "",
              ...rightLines.map((line) => truncate(line, safeWidth)),
            ];

        const controls: string[] = ["j/k move", "tab pane", "l log", "g commits", "r refresh", "q close"];
        if (payload && isPausableRun(payload.run.status)) {
          controls.push("p pause");
        } else if (payload && isResumableRun(payload.run.status)) {
          controls.push("p resume");
        }
        if (payload && isCancellableRun(payload.run.status)) {
          controls.push("c cancel");
        }
        if (payload && isRetryableRun(payload.run.status)) {
          controls.push("f retry failed");
        }
        if (canRetryMerge(payload)) {
          controls.push("m retry merge");
        }

        return [
          ...header,
          ...body,
          "",
          truncate(statusLine, safeWidth),
          truncate(controls.join(" • "), safeWidth),
        ];
      },

      invalidate() {
        // Stateless rendering.
      },
    };
  });
}

import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";

export type NotifyLevel = "info" | "warning" | "error" | "success";

export type UiApi = {
  notify?: (message: string, level?: NotifyLevel) => void;
  setStatus?: (id: string, status: string | undefined) => void;
  setWidget?: (id: string, widget: unknown) => void;
  confirm?: (title: string, message: string) => Promise<boolean>;
  custom?: <T>(
    factory: (
      tui: { requestRender: (full?: boolean) => void; stop: () => void; start: () => void },
      theme: unknown,
      keybindings: unknown,
      done: (result: T) => void,
    ) => {
      render: (width: number) => string[];
      handleInput?: (data: string) => void;
      invalidate?: () => void;
    },
    options?: { overlay?: boolean; overlayOptions?: unknown; onHandle?: (handle: unknown) => void },
  ) => Promise<T>;
};

export type ExtensionCommandContext = {
  ui: UiApi;
  hasUI?: boolean;
  cwd?: string;
};

export type ExtensionAPI = {
  registerCommand: (
    name: string,
    options: {
      description: string;
      handler: (args: string | undefined, ctx: ExtensionCommandContext) => Promise<void> | void;
    },
  ) => void;
  on?: (
    eventName: string,
    handler: (event: unknown, ctx: ExtensionCommandContext) => Promise<void> | void,
  ) => void;
};

export type WorkspaceSummary = {
  id: string;
  label: string;
  path: string;
  domains?: string[];
};

export type ApiError = Error & { status?: number; body?: string };

export function getBaseUrl(): string {
  return (process.env.RORCA_BASE_URL?.trim() || "http://localhost:3030").replace(/\/$/, "");
}

export function readDefaultToken(): string | undefined {
  const tokenPath = path.join(os.homedir(), ".rorca", "mcp-token");
  if (!existsSync(tokenPath)) {
    return undefined;
  }

  try {
    const token = readFileSync(tokenPath, "utf8").trim();
    return token || undefined;
  } catch {
    return undefined;
  }
}

export function notify(ui: UiApi | undefined, message: string, level: NotifyLevel = "info"): void {
  if (typeof ui?.notify === "function") {
    ui.notify(message, level);
    return;
  }

  const prefix = level === "error" ? "[rorca:error]" : level === "warning" ? "[rorca:warn]" : "[rorca]";
  const text = `${prefix} ${message}`;
  if (level === "error") {
    console.error(text);
  } else if (level === "warning") {
    console.warn(text);
  } else {
    console.log(text);
  }
}

export function buildHeaders(token?: string, extra?: Record<string, string>): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...extra,
  };
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }
  return headers;
}

export async function apiFetchJson<T>(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<T> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return (await response.json()) as T;
}

export async function apiFetchText(
  baseUrl: string,
  pathname: string,
  options: { method?: string; body?: unknown; token?: string } = {},
): Promise<string> {
  const response = await fetch(`${baseUrl}${pathname}`, {
    method: options.method ?? (options.body == null ? "GET" : "POST"),
    headers: buildHeaders(options.token, options.body == null ? undefined : { "Content-Type": "application/json" }),
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    const error = new Error(`HTTP ${response.status} ${response.statusText} for ${pathname}`) as ApiError;
    error.status = response.status;
    error.body = body;
    throw error;
  }

  return response.text();
}

export async function getWorkspaces(baseUrl: string, token?: string): Promise<WorkspaceSummary[]> {
  const payload = await apiFetchJson<{ items?: WorkspaceSummary[] }>(baseUrl, "/api/workspaces", { token });
  return payload.items ?? [];
}

export async function resolveWorkspace(
  baseUrl: string,
  token?: string,
  preferredWorkspaceId?: string,
  cwdHint?: string,
): Promise<WorkspaceSummary> {
  const envId = preferredWorkspaceId || process.env.RORCA_WORKSPACE_ID?.trim();
  const workspaces = await getWorkspaces(baseUrl, token);
  if (workspaces.length === 0) {
    throw new Error("No workspaces registered in Rorca");
  }

  if (envId) {
    const match = workspaces.find((workspace) => workspace.id === envId);
    if (match) {
      return match;
    }
  }

  const candidateCwds = [cwdHint?.trim(), process.cwd()].filter((value): value is string => Boolean(value));
  for (const cwd of candidateCwds) {
    const cwdMatch = workspaces.find((workspace) => cwd === workspace.path || cwd.startsWith(`${workspace.path}${path.sep}`));
    if (cwdMatch) {
      return cwdMatch;
    }
  }

  return workspaces[0]!;
}

export function truncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `${value.slice(0, Math.max(0, max - 3))}...`;
}

export function leftTruncate(value: string, max: number): string {
  if (max <= 0) {
    return "";
  }
  return value.length <= max ? value : `...${value.slice(-(max - 3))}`;
}

export function pad(value: string, width: number): string {
  if (width <= 0) {
    return "";
  }
  if (value.length >= width) {
    return value.slice(0, width);
  }
  return value + " ".repeat(width - value.length);
}

export function timeAgo(iso: string | null | undefined): string {
  if (!iso) {
    return "unknown";
  }

  const elapsedMs = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(elapsedMs)) {
    return "unknown";
  }
  if (elapsedMs < 60_000) {
    return "<1m";
  }
  const minutes = Math.floor(elapsedMs / 60_000);
  if (minutes < 60) {
    return `${minutes}m ago`;
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours}h ago`;
  }
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export function normalizeKey(chunk: string): string {
  switch (chunk) {
    case "\u0003":
      return "ctrl+c";
    case "\r":
    case "\n":
      return "enter";
    case "\u001b":
      return "escape";
    case "\u001b[A":
      return "up";
    case "\u001b[B":
      return "down";
    case "\u001b[C":
      return "right";
    case "\u001b[D":
      return "left";
    case "\t":
      return "tab";
    default:
      return chunk;
  }
}

export function readJsonFile<T>(filePath: string, fallback: T): T {
  if (!existsSync(filePath)) {
    return fallback;
  }
  try {
    return JSON.parse(readFileSync(filePath, "utf8")) as T;
  } catch {
    return fallback;
  }
}

export function writeJsonAtomic(filePath: string, value: unknown): void {
  const tmpFilePath = `${filePath}.tmp`;
  writeFileSync(tmpFilePath, JSON.stringify(value, null, 2), "utf8");
  renameSync(tmpFilePath, filePath);
}

export function decodeOutputLines(payload: unknown): string[] {
  if (!payload || typeof payload !== "object") {
    return [];
  }
  const output = (payload as { output?: unknown }).output;
  return Array.isArray(output) ? output.map((line) => String(line)) : [];
}

import { spawnSync } from "node:child_process";
import { openRunView } from "./tui/run-view.js";
import {
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  getBaseUrl,
  notify,
  readDefaultToken,
  resolveWorkspace,
} from "./tui/shared.js";

type PipelineRunListItem = {
  id: number;
  status: string;
  spec_path?: string;
  started_at?: string;
};

type PipelineRunListResponse = {
  items?: PipelineRunListItem[];
};

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

function escapeAppleScript(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function sortRunCandidates(items: PipelineRunListItem[]): PipelineRunListItem[] {
  const priority = new Map<string, number>([
    ["running", 0],
    ["paused", 1],
    ["queued", 2],
    ["cancelling", 3],
    ["failed", 4],
    ["partial_failure", 5],
    ["done", 6],
    ["passed", 7],
    ["cancelled", 8],
  ]);

  return [...items].sort((left, right) => {
    const leftPriority = priority.get(left.status) ?? 99;
    const rightPriority = priority.get(right.status) ?? 99;
    if (leftPriority !== rightPriority) {
      return leftPriority - rightPriority;
    }
    return right.id - left.id;
  });
}

export default function rorcaPiExtension(pi: ExtensionAPI) {
  const baseUrl = getBaseUrl();
  const token = readDefaultToken();
  let activeWorkspaceId = process.env.RORCA_WORKSPACE_ID?.trim() || "";

  const ensureWorkspace = async (ctx?: ExtensionCommandContext) => {
    if (activeWorkspaceId) {
      return activeWorkspaceId;
    }
    const workspace = await resolveWorkspace(baseUrl, token, activeWorkspaceId || undefined, ctx?.cwd);
    activeWorkspaceId = workspace.id;
    process.env.RORCA_WORKSPACE_ID = workspace.id;
    process.env.RORCA_WORKSPACE_NAME = workspace.label;
    process.env.RORCA_WORKSPACE_PATH = workspace.path;
    return activeWorkspaceId;
  };

  const withWorkspace = (handler: (workspaceId: string, ctx: ExtensionCommandContext, args?: string) => Promise<void>) => {
    return async (args: string | undefined, ctx: ExtensionCommandContext) => {
      try {
        const workspaceId = await ensureWorkspace(ctx);
        await handler(workspaceId, ctx, args);
      } catch (error) {
        notify(ctx.ui, error instanceof Error ? error.message : String(error), "error");
      }
    };
  };

  const notifyEmbeddedDisabled = (ctx: ExtensionCommandContext, feature: string) => {
    notify(
      ctx.ui,
      `${feature} is temporarily disabled in embedded Pi mode because it was corrupting the Pi terminal. Use /rorca-tui instead.`,
      "warning",
    );
  };

  const resolveRunId = async (workspaceId: string, args?: string): Promise<number> => {
    const requested = args?.trim();
    if (requested && /^\d+$/.test(requested)) {
      return Number(requested);
    }

    const runs = await apiFetchJson<PipelineRunListResponse>(
      baseUrl,
      `/api/pipeline/runs?workspaceId=${encodeURIComponent(workspaceId)}&limit=100`,
      { token },
    );
    const items = runs.items ?? [];

    if (items.length === 0) {
      throw new Error("No pipeline runs exist for the active workspace yet.");
    }

    if (requested) {
      const matched = items.find((item) => extractSpecSlug(item.spec_path) === requested);
      if (!matched) {
        throw new Error(`No pipeline run found for spec ${requested}.`);
      }
      return matched.id;
    }

    return sortRunCandidates(items)[0]!.id;
  };

  pi.registerCommand("rorca:board", {
    description: "Open the Rorca spec board",
    handler: withWorkspace(async (_workspaceId, ctx) => {
      notifyEmbeddedDisabled(ctx, "Rorca board");
    }),
  });

  pi.registerCommand("rorca:run", {
    description: "Open the Pi-native Rorca run cockpit. Args: run id, spec slug, or nothing for the latest active run.",
    handler: withWorkspace(async (workspaceId, ctx, args) => {
      const runId = await resolveRunId(workspaceId, args);
      await openRunView(ctx, pi, runId, baseUrl, token);
    }),
  });

  pi.registerCommand("rorca:memory", {
    description: "Open the Rorca memory browser",
    handler: withWorkspace(async (_workspaceId, ctx) => {
      notifyEmbeddedDisabled(ctx, "Rorca memory browser");
    }),
  });

  pi.registerCommand("rorca:direction", {
    description: "Open the Rorca direction stack view",
    handler: withWorkspace(async (_workspaceId, ctx) => {
      notifyEmbeddedDisabled(ctx, "Rorca direction view");
    }),
  });

  pi.registerCommand("rorca:workspace", {
    description: "Open the Rorca workspace switcher",
    handler: withWorkspace(async (_workspaceId, ctx) => {
      notifyEmbeddedDisabled(ctx, "Rorca workspace view");
    }),
  });

  pi.registerCommand("rorca-tui", {
    description: "Open the Rorca TUI in Terminal.app",
    handler: async (_args, ctx) => {
      const cwd = process.cwd();
      const shellCommand = `cd ${shellQuote(cwd)} && clear && rorca tui`;
      const result = spawnSync(
        "osascript",
        [
          "-e",
          'tell application "Terminal"',
          "-e",
          "activate",
          "-e",
          `do script \"${escapeAppleScript(shellCommand)}\"`,
          "-e",
          "end tell",
        ],
        { env: process.env },
      );

      if (result.status !== 0) {
        const stderr = result.stderr?.toString("utf8").trim();
        throw new Error(stderr || "Failed to launch Terminal.app for rorca tui");
      }

      notify(ctx.ui, "Opened Rorca TUI in Terminal.app", "success");
    },
  });

  pi.on?.("session_start", async (_event, ctx) => {
    try {
      const workspace = await resolveWorkspace(baseUrl, token, activeWorkspaceId || undefined, ctx.cwd);
      activeWorkspaceId = workspace.id;
      process.env.RORCA_WORKSPACE_ID = workspace.id;
      process.env.RORCA_WORKSPACE_NAME = workspace.label;
      process.env.RORCA_WORKSPACE_PATH = workspace.path;

      notify(ctx.ui, `Rorca extension ready for ${workspace.label}`, "success");

      void Promise.allSettled([
        fetch(`${baseUrl}/api/recall?workspaceId=${encodeURIComponent(workspace.id)}&titlesOnly=true`, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        }),
        fetch(`${baseUrl}/api/workspaces/${encodeURIComponent(workspace.id)}/health`, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        }),
      ]);
    } catch (error) {
      notify(ctx.ui, `Rorca extension degraded: ${error instanceof Error ? error.message : String(error)}`, "warning");
    }
  });

  pi.on?.("agent_end", async () => {
    // no-op
  });

  pi.on?.("session_shutdown", async () => {
    // no-op
  });
}

